class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        n = len(nums)
        res = 0
        i = 0
        while i < n:
            if nums[i] > 0:
                res = max(res, res * nums[i])
            else:
                if i + 1 < n and nums[i + 1] > 0:
                    res = max(res, res * nums[i + 1])
                i += 1
        return res

